class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.spy_comparisons = deque(maxlen=2)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                self.spy_comparisons.append(
                    (float(spy_bar.Close), float(self.spy_sma.Current.Value))
                )

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            aapl_close = float(aapl_bar.Close)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if self.IsWarmingUp:
            return
        if len(self.spy_comparisons) < 2 or not self.aapl_rsi.IsReady:
            return

        previous_spy_close, previous_spy_sma = self.spy_comparisons[0]
        current_spy_close, current_spy_sma = self.spy_comparisons[1]

        # Sells are evaluated before buys.
        if self.Portfolio[spy].Invested:
            crossed_below = (
                previous_spy_close >= previous_spy_sma
                and current_spy_close < current_spy_sma
            )
            if crossed_below:
                self.Liquidate(spy, "Strategy A: close crossed below SMA(100)")

        if self.Portfolio[aapl].Invested and self.aapl_rsi.Current.Value > 60:
            self.Liquidate(aapl, "Strategy B: RSI(14) above 60")

        if not self.Portfolio[spy].Invested:
            crossed_above = (
                previous_spy_close <= previous_spy_sma
                and current_spy_close > current_spy_sma
            )
            if crossed_above:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(
                        spy, quantity, tag="Strategy A: close crossed above SMA(100)"
                    )

        if not self.Portfolio[aapl].Invested and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.Portfolio.Cash >= cash_to_invest:
                quantity = floor(cash_to_invest / float(data.Bars[aapl].Close))
                if quantity > 0:
                    self.MarketOrder(
                        aapl, quantity, tag="Strategy B: three consecutive red days"
                    )

