class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        # Keeping 101 closes makes both today's and yesterday's 100-day SMA
        # available without using data from before the corresponding close.
        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        # Each strategy owns and accounts for its own private lot.
        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def OnData(self, data):
        all_bars_present = all(data.Bars.ContainsKey(symbol) for symbol in self.symbols)

        # Market-state calculations continue whenever their own ticker has a bar,
        # even on a date for which trading rules must be skipped.
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.append(float(data.Bars[self.spy].Close))

        if data.Bars.ContainsKey(self.aapl):
            aapl_bar = data.Bars[self.aapl]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not all_bars_present:
            return

        self._run_spy_strategy(float(data.Bars[self.spy].Close))
        self._run_aapl_strategy(float(data.Bars[self.aapl].Close))

    def _run_spy_strategy(self, close):
        if len(self.spy_closes) < 101 or self.spy_order_pending:
            return

        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[:-1]) / 100.0
        today_sma = sum(closes[1:]) / 100.0
        crossed_above = closes[-2] <= yesterday_sma and close > today_sma
        crossed_below = closes[-2] >= yesterday_sma and close < today_sma

        # Sells are evaluated before buys, and only the applicable side of the
        # strategy is evaluated for the current private-lot state.
        if self.spy_lot > 0:
            if crossed_below:
                self._submit_lot_order("spy", self.spy, -self.spy_lot)
            return

        if crossed_above:
            quantity = self.CalculateOrderQuantity(self.spy, 0.40)
            if quantity > 0:
                self._submit_lot_order("spy", self.spy, quantity)

    def _run_aapl_strategy(self, close):
        if not self.aapl_rsi.IsReady or self.aapl_order_pending:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self._submit_lot_order("aapl", self.aapl, -self.aapl_lot)
            return

        if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000.0:
            quantity = floor(20_000.0 / close)
            if quantity > 0:
                self._submit_lot_order("aapl", self.aapl, quantity)

    def _submit_lot_order(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity, False, strategy)
        self.pending_orders[ticket.OrderId] = strategy
        if strategy == "spy":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True

    def OnOrderEvent(self, order_event):
        strategy = self.pending_orders.get(order_event.OrderId)
        if strategy is None:
            return

        fill_quantity = int(order_event.FillQuantity)
        if strategy == "spy":
            self.spy_lot = max(0, self.spy_lot + fill_quantity)
        else:
            self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            del self.pending_orders[order_event.OrderId]
            if strategy == "spy":
                self.spy_order_pending = False
            else:
                self.aapl_order_pending = False

