        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.spy_observations = deque(maxlen=2)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # Market-state quantities continue to advance even on a day on which
        # another subscribed security has no bar.
        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                self.spy_observations.append((spy_bar.Close, self.spy_sma.Current.Value))

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Sells are evaluated before buys.  These two slots otherwise operate
        # independently and each quantity records only that strategy's lot.
        spy_crossed_below = False
        spy_crossed_above = False
        if len(self.spy_observations) == 2:
            previous_close, previous_sma = self.spy_observations[0]
            current_close, current_sma = self.spy_observations[1]
            spy_crossed_below = previous_close >= previous_sma and current_close < current_sma
            spy_crossed_above = previous_close <= previous_sma and current_close > current_sma

        if self.spy_lot != 0 and spy_crossed_below:
            self.MarketOrder(spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot != 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_rsi.IsReady and self.aapl_red_streak >= 3:
            cash_amount = 20_000
            if self.Portfolio.Cash >= cash_amount:
                quantity = floor(cash_amount / data.Bars[aapl].Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

