class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

    def OnData(self, data):
        bars = {}
        complete_day = True
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]
            else:
                complete_day = False

        spy_bar = bars.get("SPY")
        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            current_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = current_spy_sma
        else:
            current_spy_sma = None

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not complete_day:
            return

        # Sells are evaluated before buys. Each pending order also reserves its
        # strategy's private lot until LEAN reports the fill or cancellation.
        if self.spy_lot > 0 and not self._has_pending("SPY"):
            crossed_below = (
                previous_spy_close is not None
                and previous_spy_sma is not None
                and current_spy_sma is not None
                and previous_spy_close >= previous_spy_sma
                and spy_bar.Close < current_spy_sma
            )
            if crossed_below:
                self._place_order("SPY", -self.spy_lot)

        if self.aapl_lot > 0 and not self._has_pending("AAPL"):
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self._place_order("AAPL", -self.aapl_lot)

        if self.spy_lot == 0 and not self._has_pending("SPY"):
            crossed_above = (
                previous_spy_close is not None
                and previous_spy_sma is not None
                and current_spy_sma is not None
                and previous_spy_close <= previous_spy_sma
                and spy_bar.Close > current_spy_sma
            )
            if crossed_above:
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self._place_order("SPY", quantity)

        if self.aapl_lot == 0 and not self._has_pending("AAPL"):
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20000:
                quantity = int(20000 // aapl_bar.Close)
                if quantity > 0:
                    self._place_order("AAPL", quantity)

    def _has_pending(self, strategy):
        return strategy in self.pending_orders.values()

    def _place_order(self, strategy, quantity):
        ticket = self.MarketOrder(self.symbols[strategy], quantity)
        self.pending_orders[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        strategy = self.pending_orders.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.FillQuantity != 0:
            if strategy == "SPY":
                self.spy_lot += order_event.FillQuantity
            else:
                self.aapl_lot += order_event.FillQuantity

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            del self.pending_orders[order_event.OrderId]

