            bar = bars[symbol]
            previous_close = self.previous_closes.get(symbol)

            if ticker == "AAPL" and previous_close is not None:
                if bar.Close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            if ticker == "SPY":
                self.spy_sma.Update(bar.EndTime, bar.Close)
            elif ticker == "AAPL":
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

            self.previous_closes[symbol] = bar.Close

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_above_sma = None
        if bars.ContainsKey(spy) and self.spy_sma.IsReady:
            spy_above_sma = bars[spy].Close > self.spy_sma.Current.Value

        all_bars_present = all(
            bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )
        all_state_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_above_sma is not None
            and all(symbol in self.previous_closes for symbol in self.symbols.values())
        )

        if all_bars_present and all_state_ready:
            spy_crossed_below = self.previous_spy_above_sma and not spy_above_sma

            # Sells are evaluated before buys across both independent slots.
            if self.spy_lot > 0 and spy_crossed_below:
                self.MarketOrder(spy, -self.spy_lot)
                self.spy_lot = 0

            if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.aapl_lot)
                self.aapl_lot = 0

            spy_crossed_above = not self.previous_spy_above_sma and spy_above_sma

            if self.spy_lot == 0 and spy_crossed_above:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(spy, quantity)
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                cash_to_invest = 20_000
                if self.Portfolio.Cash >= cash_to_invest:
                    quantity = int(cash_to_invest // bars[aapl].Close)
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
                        self.aapl_lot = quantity

        if spy_above_sma is not None:
            self.previous_spy_above_sma = spy_above_sma

