        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        # Each subscribed trade ticker belongs to exactly one private strategy lot.
        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_order_pending = False
        self.strategy_b_order_pending = False

    def OnData(self, data):
        bars = data.Bars

        # These tickers are exclusive to their strategies, so the security
        # holdings are the authoritative private-lot sizes (including splits).
        self.strategy_a_lot = int(self.Portfolio[self.spy].Quantity)
        self.strategy_b_lot = int(self.Portfolio[self.aapl].Quantity)

        # Market-state observations continue to advance even when another ticker's
        # bar is absent, but no strategy rule is evaluated on an incomplete day.
        if bars.ContainsKey(self.aapl):
            aapl_close = bars[self.aapl].Close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        spy_close = None
        spy_sma = None
        if bars.ContainsKey(self.spy):
            spy_close = bars[self.spy].Close
            if self.spy_sma.IsReady:
                spy_sma = self.spy_sma.Current.Value

        complete_day = all(bars.ContainsKey(symbol) for symbol in self.symbols)
        if complete_day:
            a_was_invested = self.strategy_a_lot > 0
            b_was_invested = self.strategy_b_lot > 0

            # Sells are evaluated before buys.  Each strategy evaluates only the
            # side appropriate to whether its own lot is empty.
            if a_was_invested and not self.strategy_a_order_pending:
                crossed_below = (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                    and spy_sma is not None
                    and self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < spy_sma
                )
                if crossed_below:
                    self.strategy_a_order_pending = True
                    self.MarketOrder(self.spy, -self.strategy_a_lot)

            if b_was_invested and not self.strategy_b_order_pending:
                if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                    self.strategy_b_order_pending = True
                    self.MarketOrder(self.aapl, -self.strategy_b_lot)

            if not a_was_invested and not self.strategy_a_order_pending:
                crossed_above = (
                    self.spy_sma.IsReady
                    and self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                    and self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > spy_sma
                )
                if crossed_above:
                    quantity = int(
                        (self.Portfolio.TotalPortfolioValue * 0.40) // spy_close
                    )
                    if quantity > 0:
                        self.strategy_a_order_pending = True
                        self.MarketOrder(self.spy, quantity)

            if not b_was_invested and not self.strategy_b_order_pending:
                if self.aapl_rsi.IsReady and self.aapl_red_streak >= 3:
                    cash_to_invest = 20_000
                    if self.Portfolio.Cash >= cash_to_invest:
                        quantity = int(cash_to_invest // bars[self.aapl].Close)
                        if quantity > 0:
                            self.strategy_b_order_pending = True
                            self.MarketOrder(self.aapl, quantity)

        # Save SPY's values on every SPY trading day so a cross always compares
        # adjacent SPY daily observations, including across an incomplete day.
        if spy_close is not None and spy_sma is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self.spy:
            if order_event.FillQuantity != 0:
                self.strategy_a_lot += int(order_event.FillQuantity)
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled,
                                      OrderStatus.Invalid]:
                self.strategy_a_order_pending = False
        elif order_event.Symbol == self.aapl:
            if order_event.FillQuantity != 0:
                self.strategy_b_lot += int(order_event.FillQuantity)
            if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled,
                                      OrderStatus.Invalid]:
                self.strategy_b_order_pending = False

