            self.spy_previous_relation is not None
            and self.spy_previous_relation <= 0
            and spy_relation is not None
            and spy_relation > 0
        )
        spy_crosses_below = (
            self.spy_previous_relation is not None
            and self.spy_previous_relation >= 0
