class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False
        self.order_strategies = {}

    def OnData(self, data):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_crossed_above = False
        spy_crossed_below = False

        if bars.ContainsKey(spy):
            spy_close = bars[spy].Close
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100
                if self.spy_previous_sma is not None:
                    spy_crossed_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and spy_close > spy_sma
                    )
                    spy_crossed_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and spy_close < spy_sma
                    )
                self.spy_previous_sma = spy_sma
                self.spy_previous_close = spy_close

        if bars.ContainsKey(aapl):
            aapl_bar = bars[aapl]
            aapl_close = aapl_bar.Close
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Slot 1: Strategy A.  Sells are evaluated before buys.
        if not self.spy_order_pending:
            if self.spy_lot > 0:
                if spy_crossed_below:
                    self._submit_order(spy, -self.spy_lot, "A")
            elif self.spy_previous_sma is not None and spy_crossed_above:
                quantity = floor(0.40 * self.Portfolio.TotalPortfolioValue / bars[spy].Close)
                if quantity > 0:
                    self._submit_order(spy, quantity, "A")

        # Slot 2: Strategy B.  Both of its rules wait for its RSI to be ready.
        if not self.aapl_order_pending and self.aapl_rsi.IsReady:
            if self.aapl_lot > 0:
                if self.aapl_rsi.Current.Value > 60:
                    self._submit_order(aapl, -self.aapl_lot, "B")
            elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / bars[aapl].Close)
                if quantity > 0:
                    self._submit_order(aapl, quantity, "B")

    def _submit_order(self, symbol, quantity, strategy):
        if strategy == "A":
            self.spy_order_pending = True
        else:
            self.aapl_order_pending = True

        ticket = self.MarketOrder(symbol, quantity, False, "Strategy " + strategy)
        self.order_strategies[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order is not None:
                if order.Tag == "Strategy A":
                    strategy = "A"
                elif order.Tag == "Strategy B":
                    strategy = "B"
        if strategy is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if strategy == "A":
                self.spy_lot += int(order_event.FillQuantity)
            else:
                self.aapl_lot += int(order_event.FillQuantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            if strategy == "A":
                self.spy_order_pending = False
            else:
                self.aapl_order_pending = False

