        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_tickers = set()

    def OnData(self, data: Slice):
        bars = {
            ticker: data.Bars[symbol] if data.Bars.ContainsKey(symbol) else None
            for ticker, symbol in self.symbols.items()
        }

        spy_bar = bars["SPY"]
        previous_spy_close = self.spy_closes[-1] if self.spy_closes else None
        previous_spy_sma = (
            sum(list(self.spy_closes)[-100:]) / 100
            if len(self.spy_closes) >= 100
            else None
        )
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))

        aapl_bar = bars["AAPL"]
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        if any(bar is None for bar in bars.values()):
            return

        spy_close = float(spy_bar.Close)
        current_spy_sma = (
            sum(self.spy_closes) / 100 if len(self.spy_closes) >= 100 else None
        )

        if self.spy_lot > 0 and not self._has_pending("SPY"):
            if (
                previous_spy_sma is not None
                and previous_spy_close >= previous_spy_sma
                and spy_close < current_spy_sma
            ):
                self._submit("SPY", -self.spy_lot)

        if self.aapl_lot > 0 and not self._has_pending("AAPL"):
            if self.aapl_rsi.IsReady and float(self.aapl_rsi.Current.Value) > 60:
                self._submit("AAPL", -self.aapl_lot)

        if self.spy_lot == 0 and not self._has_pending("SPY"):
            if (
                previous_spy_sma is not None
                and previous_spy_close <= previous_spy_sma
                and spy_close > current_spy_sma
            ):
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self._submit("SPY", quantity)

        if self.aapl_lot == 0 and not self._has_pending("AAPL"):
            if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                quantity = floor(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self._submit("AAPL", quantity)

    def _submit(self, ticker, quantity):
        self.pending_tickers.add(ticker)
        ticket = self.MarketOrder(self.symbols[ticker], quantity, False, ticker)
        return ticket

    def _has_pending(self, ticker):
        return ticker in self.pending_tickers

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None or order.Tag not in ("SPY", "AAPL"):
            return
        ticker = order.Tag

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if ticker == "SPY":
                self.spy_lot += int(order_event.FillQuantity)
            else:
                self.aapl_lot += int(order_event.FillQuantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self.pending_tickers.discard(ticker)

