class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        # The extra SPY value permits both today's and yesterday's fully formed
        # 100-day SMA to be calculated from closes ending on their respective days.
        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        # Each strategy owns only the shares recorded in its private lot.
        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

    def on_data(self, data: Slice):
        bars = data.bars

        # Market-state quantities continue to consume every available observation,
        # even on a date on which another subscribed security has no bar.
        spy_bar = bars[self.symbols["SPY"]] if self.symbols["SPY"] in bars else None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))

        aapl_bar = (
            bars[self.symbols["AAPL"]]
            if self.symbols["AAPL"] in bars
            else None
        )
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        # Every rule is skipped unless all five securities supplied today's bar.
        if any(symbol not in bars for symbol in self.symbols.values()):
            return

        # Sells are evaluated before any buys.
        if self.strategy_a_quantity > 0 and self._spy_crosses_below_sma():
            self.market_order(self.symbols["SPY"], -self.strategy_a_quantity)
            self.strategy_a_quantity = 0

        if (
            self.strategy_b_quantity > 0
            and self.aapl_rsi.is_ready
            and self.aapl_rsi.current.value > 60
        ):
            self.market_order(self.symbols["AAPL"], -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

        if self.strategy_a_quantity == 0 and self._spy_crosses_above_sma():
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.strategy_a_quantity = quantity

        if self.strategy_b_quantity == 0 and self.aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                quantity = floor(20_000 / float(aapl_bar.close))
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.strategy_b_quantity = quantity

    def _spy_crosses_above_sma(self):
        if len(self.spy_closes) < 101:
            return False
        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[:100]) / 100
        today_sma = sum(closes[1:]) / 100
        return closes[-2] <= yesterday_sma and closes[-1] > today_sma

    def _spy_crosses_below_sma(self):
        if len(self.spy_closes) < 101:
            return False
        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[:100]) / 100
        today_sma = sum(closes[1:]) / 100
        return closes[-2] >= yesterday_sma and closes[-1] < today_sma

