class DailySmaAndRsiAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_sma_difference = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

        # Warm-up supplies enough observations for both the 100-day SMA and
        # the 14-day RSI before any strategy is allowed to trade.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_crosses_above = False
        spy_crosses_below = False

        if spy in data.Bars:
            spy_close = data.Bars[spy].Close
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100
                spy_sma_difference = spy_close - spy_sma
                if self.previous_spy_sma_difference is not None:
                    spy_crosses_above = (
                        self.previous_spy_sma_difference <= 0
                        and spy_sma_difference > 0
                    )
                    spy_crosses_below = (
                        self.previous_spy_sma_difference >= 0
                        and spy_sma_difference < 0
                    )
                self.previous_spy_sma_difference = spy_sma_difference

        if aapl in data.Bars:
            aapl_bar = data.Bars[aapl]
            aapl_close = aapl_bar.Close
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        # Market-state calculations above continue even on an incomplete
        # slice, but no rule is evaluated unless every subscribed bar exists.
        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return
        if self.IsWarmingUp:
            return
        if len(self.spy_closes) < 100 or not self.aapl_rsi.IsReady:
            return

        # Evaluate every sell before evaluating either strategy's buy.
        if self.spy_lot > 0 and spy_crosses_below:
            self.MarketOrder(spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crosses_above:
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / data.Bars[aapl].Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

