class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]
        self.closes = {
            symbol: deque(maxlen=101) for symbol in self.symbols.values()
        }
        self.aapl_red_streak = 0
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        for symbol in self.symbols.values():
            if data.Bars.ContainsKey(symbol):
                close = data.Bars[symbol].Close
                history = self.closes[symbol]
                if symbol == self.aapl and history:
                    if close < history[-1]:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0
                history.append(close)

        if self.IsWarmingUp:
            return
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return
        if len(self.closes[self.spy]) < 101 or not self.aapl_rsi.IsReady:
            return

        spy_invested = self.Portfolio[self.spy].Quantity != 0
        aapl_invested = self.Portfolio[self.aapl].Quantity != 0

        spy_history = self.closes[self.spy]
        previous_spy_sma = sum(list(spy_history)[:100]) / 100
        current_spy_sma = sum(list(spy_history)[1:]) / 100
        spy_crossed_below = (
            spy_history[-2] >= previous_spy_sma
            and spy_history[-1] < current_spy_sma
        )
        spy_crossed_above = (
            spy_history[-2] <= previous_spy_sma
            and spy_history[-1] > current_spy_sma
        )

        if spy_invested and spy_crossed_below:
            self.Liquidate(self.spy)
        if aapl_invested and self.aapl_rsi.Current.Value > 60:
            self.Liquidate(self.aapl)

        spy_invested = self.Portfolio[self.spy].Quantity != 0
        aapl_invested = self.Portfolio[self.aapl].Quantity != 0

        if not spy_invested and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(self.spy, 0.40)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)

        if not aapl_invested and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.Portfolio.Cash >= cash_to_invest:
                quantity = int(cash_to_invest / data.Bars[self.aapl].Close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)

