class IndependentSpyAndAppleStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_relation = None
        self.spy_lot = 0

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_changes = deque(maxlen=14)
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None
        self.aapl_lot = 0

    def OnData(self, data):
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        self._apply_splits(data)

        spy_close = float(data.Bars[self.symbols["SPY"]].Close)
        aapl_close = float(data.Bars[self.symbols["AAPL"]].Close)

        spy_crossed_above, spy_crossed_below = self._update_spy_sma(spy_close)
        self._update_aapl_state(aapl_close)

        # All sell rules are evaluated before either strategy's buy rule.
        if self.spy_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi is not None and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = int(self.CalculateOrderQuantity(self.symbols["SPY"], 0.40))
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if float(self.Portfolio.Cash) >= cash_to_invest:
                quantity = floor(cash_to_invest / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _update_spy_sma(self, close):
        self.spy_closes.append(close)
        if len(self.spy_closes) < 100:
            return False, False

        relation = close - (sum(self.spy_closes) / 100.0)
        crossed_above = (
            self.spy_previous_relation is not None
            and self.spy_previous_relation <= 0
            and relation > 0
        )
        crossed_below = (
            self.spy_previous_relation is not None
            and self.spy_previous_relation >= 0
            and relation < 0
        )
        self.spy_previous_relation = relation
        return crossed_above, crossed_below

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is None:
            self.aapl_previous_close = close
            return

        change = close - self.aapl_previous_close
        self.aapl_red_streak = self.aapl_red_streak + 1 if change < 0 else 0
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.aapl_average_gain is None:
            self.aapl_rsi_changes.append((gain, loss))
            if len(self.aapl_rsi_changes) == 14:
                self.aapl_average_gain = sum(x[0] for x in self.aapl_rsi_changes) / 14.0
                self.aapl_average_loss = sum(x[1] for x in self.aapl_rsi_changes) / 14.0
                self.aapl_rsi = self._rsi_value()
        else:
            self.aapl_average_gain = (self.aapl_average_gain * 13.0 + gain) / 14.0
            self.aapl_average_loss = (self.aapl_average_loss * 13.0 + loss) / 14.0
            self.aapl_rsi = self._rsi_value()

        self.aapl_previous_close = close

    def _rsi_value(self):
        if self.aapl_average_loss == 0:
            return 100.0 if self.aapl_average_gain > 0 else 50.0
        relative_strength = self.aapl_average_gain / self.aapl_average_loss
        return 100.0 - 100.0 / (1.0 + relative_strength)

    def _apply_splits(self, data):
        for ticker, lot_name in [("SPY", "spy_lot"), ("AAPL", "aapl_lot")]:
            symbol = self.symbols[ticker]
            if not data.Splits.ContainsKey(symbol):
                continue
            split = data.Splits[symbol]
            if split.Type != SplitType.SplitOccurred or split.SplitFactor == 0:
                continue
            current_lot = getattr(self, lot_name)
            if current_lot > 0:
                setattr(self, lot_name, int(current_lot / float(split.SplitFactor)))

