        self.strategy_b_shares = 0

        # One extra sample supplies the prior fully formed SMA value needed for
        # the first possible crossover comparison.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        spy_bar = self._bar(data, self.symbols["SPY"])
        aapl_bar = self._bar(data, self.symbols["AAPL"])

