class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]
        self.spy_sma = self.sma(self.spy, 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(
            self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        # The extra bar supplies the prior close/indicator pair needed by the
        # crossover rule once the 100-day SMA itself is ready.
        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        self._apply_splits(data)

        spy_bar = data.bars[self.spy] if data.bars.contains_key(self.spy) else None
        aapl_bar = data.bars[self.aapl] if data.bars.contains_key(self.aapl) else None

        if aapl_bar is not None:
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.close

        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma
        if spy_bar is not None and self.spy_sma.is_ready:
            self.previous_spy_close = spy_bar.close
            self.previous_spy_sma = self.spy_sma.current.value

        if self.is_warming_up:
            return

        # Every subscribed ticker must have a completed daily bar before any
        # strategy rule is evaluated.
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return
        if not self.spy_sma.is_ready or not self.aapl_rsi.is_ready:
            return
        if previous_spy_close is None or previous_spy_sma is None:
            return

        spy_close = spy_bar.close
        spy_sma = self.spy_sma.current.value
        spy_crossed_above = (
            previous_spy_close <= previous_spy_sma and spy_close > spy_sma
        )
        spy_crossed_below = (
            previous_spy_close >= previous_spy_sma and spy_close < spy_sma
        )

        # Sells are evaluated before buys, and each counter is the strategy's
        # private lot rather than the account-wide holding quantity.
        if self.spy_lot > 0 and spy_crossed_below:
            self.market_order(self.spy, -self.spy_lot, tag="Strategy A sell")
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.aapl, -self.aapl_lot, tag="Strategy B sell")
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = int(
                (self.portfolio.total_portfolio_value * 0.40) // spy_close
            )
            if quantity > 0:
                self.market_order(self.spy, quantity, tag="Strategy A buy")
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                quantity = int(20_000 // aapl_bar.close)
                if quantity > 0:
                    self.market_order(self.aapl, quantity, tag="Strategy B buy")
                    self.aapl_lot = quantity

    def _apply_splits(self, data: Slice):
        for symbol, attribute in ((self.spy, "spy_lot"), (self.aapl, "aapl_lot")):
            if not data.splits.contains_key(symbol):
                continue
            split = data.splits[symbol]
            if split.type != SplitType.SPLIT_OCCURRED:
                continue
            quantity = getattr(self, attribute)
            if quantity > 0:
                setattr(self, attribute, int(quantity / split.split_factor))

