class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_buy_pending = False
        self.aapl_buy_pending = False
        self.spy_sell_pending = False
        self.aapl_sell_pending = False
        self.order_strategies = {}

    def OnData(self, data):
        bars = data.Bars

        spy_bar = (
            bars[self.symbols["SPY"]]
            if bars.ContainsKey(self.symbols["SPY"])
            else None
        )
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
            spy_sma = (
                sum(self.spy_closes) / 100.0
                if len(self.spy_closes) == 100
                else None
            )
        else:
            spy_sma = None

        aapl_bar = (
            bars[self.symbols["AAPL"]]
            if bars.ContainsKey(self.symbols["AAPL"])
            else None
        )
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        complete_slice = all(
            bars.ContainsKey(self.symbols[ticker]) for ticker in self.tickers
        )
        indicators_ready = (
            spy_sma is not None
            and self.previous_spy_sma is not None
            and self.aapl_rsi.IsReady
        )
        if complete_slice and indicators_ready:
            # Every strategy's sell is evaluated before any strategy's buy.
            if self.spy_lot > 0 and not self.spy_sell_pending:
                crosses_below = (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                    and spy_sma is not None
                    and self.previous_spy_close >= self.previous_spy_sma
                    and float(spy_bar.Close) < spy_sma
                )
                if crosses_below:
                    self._submit_order("spy_sell", self.symbols["SPY"], -self.spy_lot)
                    self.spy_sell_pending = True

            if (
                self.aapl_lot > 0
                and not self.aapl_sell_pending
                and self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
            ):
                self._submit_order(
                    "aapl_sell", self.symbols["AAPL"], -self.aapl_lot
                )
                self.aapl_sell_pending = True

            if self.spy_lot == 0 and not self.spy_buy_pending:
                crosses_above = (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                    and spy_sma is not None
                    and self.previous_spy_close <= self.previous_spy_sma
                    and float(spy_bar.Close) > spy_sma
                )
                if crosses_above:
                    quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                    if quantity > 0:
                        self._submit_order("spy_buy", self.symbols["SPY"], quantity)
                        self.spy_buy_pending = True

            if (
                self.aapl_lot == 0
                and not self.aapl_buy_pending
                and self.previous_aapl_close is not None
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = floor(20_000 / float(aapl_bar.Close))
                if quantity > 0:
                    self._submit_order("aapl_buy", self.symbols["AAPL"], quantity)
                    self.aapl_buy_pending = True

        if spy_bar is not None:
            self.previous_spy_close = float(spy_bar.Close)
            if spy_sma is not None:
                self.previous_spy_sma = spy_sma
        if aapl_bar is not None:
            self.previous_aapl_close = float(aapl_bar.Close)

    def _submit_order(self, strategy, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.order_strategies[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        strategy = self.order_strategies.get(order_event.OrderId)
        if strategy is None:
            return

        fill_quantity = int(order_event.FillQuantity)
        if strategy == "spy_buy":
            self.spy_lot += max(fill_quantity, 0)
        elif strategy == "spy_sell":
            self.spy_lot = max(0, self.spy_lot + fill_quantity)
        elif strategy == "aapl_buy":
            self.aapl_lot += max(fill_quantity, 0)
        elif strategy == "aapl_sell":
            self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        if order_event.Status in [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]:
            if strategy == "spy_buy":
                self.spy_buy_pending = False
            elif strategy == "spy_sell":
                self.spy_sell_pending = False
            elif strategy == "aapl_buy":
                self.aapl_buy_pending = False
            elif strategy == "aapl_sell":
                self.aapl_sell_pending = False
            self.order_strategies.pop(order_event.OrderId, None)

